
/* LUJO ÁRABE · UX prototype V1 · IQneting · no backend, payments or real stock */
'use strict';
const ASSET_MAP = window.__LUJO_ASSETS__ || {};
function asset(path){if(/^(data:|blob:|https?:|\/)/.test(path))return path;const key=path.replace(/^assets\//,'');return ASSET_MAP[key] || (path.startsWith('assets/')?path:'assets/'+path)}

const IQ_DEMO=window.IQCommerceDemo;
if(!IQ_DEMO)throw new Error('Falta cargar el puente local del Panel Maestro');
const ORIGINAL_PRODUCTS=JSON.parse(document.getElementById('product-seed').textContent);
function makeFallback(){
 const products=ORIGINAL_PRODUCTS.map((p,i)=>({
  id:'P-'+String(i+1).padStart(2,'0'),name:p.nombre,brand:p.marca,code:'LA-'+String(i+1).padStart(3,'0'),
  price:Number(p.precio),stock:18+(i*7)%54,active:true,featured:i<3,category:p.categoria==='sets'?'c2':'c1',
  images:[asset(p.foto)],desc:p.notas||''
 }));
 return {products,categories:[{id:'c1',name:'Perfumes',active:true},{id:'c2',name:'Sets',active:true}],
 orders:[],returns:[],customers:[],coupons:[],content:[],tax:{ivaEnabled:false,ivaRate:16},
 store:{name:'Lujo Árabe'},shipping:{standard:99,freeFrom:1500,carriers:['Paquetería nacional']},catalogImportedV41:true};
}
IQ_DEMO.boot(makeFallback());
function addMissingCatalog(){
 const current=IQ_DEMO.get();
 if(current.catalogImportedV41)return;
 const known=new Set(current.products.map(p=>String(p.name||'').trim().toLowerCase()));
 const extra=makeFallback().products.filter(p=>!known.has(p.name.trim().toLowerCase())&&!current.products.some(x=>x.id===p.id));
 try{IQ_DEMO.tx(d=>{d.products.push(...extra);d.catalogImportedV41=true;if(!d.categories.length)d.categories=makeFallback().categories})}
 catch(e){console.warn('No se pudo ampliar catálogo de demostración:',e.message)}
}
addMissingCatalog();
const PRODUCTS=[];
function syncFromShared(){
 const db=IQ_DEMO.get();if(!db)return;
 const asStoreProduct=p=>{
  const original=ORIGINAL_PRODUCTS.find(x=>x.nombre.trim().toLowerCase()===String(p.name).trim().toLowerCase());
  const photo=p.images?.[0]||original?.foto||'assets/media-05.webp';
  return {
    id:String(p.id),nombre:p.name,marca:p.brand||original?.marca||'Marca',
    presentacion:original?.presentacion||'Pieza',tipo:original?.tipo||'Producto',
    genero:original?.genero||'unisex',categoria:original?.categoria||(p.category==='c2'?'sets':'arabes'),
    precio:Number(p.price),foto:asset(photo),notas:String(p.desc||original?.notas||'Fragancia'),
    badge:original?.badge||'',domainCategory:p.category,stock:IQ_DEMO.available(db,p.id)
  };
 };
 PRODUCTS.splice(0,PRODUCTS.length,...db.products.filter(p=>p.active&&!p.archived).map(asStoreProduct));
 if(window.IQ_DEMO_STATE_READY){
  const availableIds=new Set(PRODUCTS.map(p=>p.id));
  const before=S.cart.length;
  S.cart=S.cart.filter(x=>availableIds.has(String(x.id))).map(x=>({...x,id:String(x.id)}));
  if(before!==S.cart.length)persist();
 }
}
syncFromShared();

